const TEMPLATE_2408_18_B64 = "";
// ---------------------------------------------------------------------------
// DA Form 2408-18 (Equipment Inspection List) â€” coordinate-fill path.
//
// Unlike pdfgen-vanilla-multi (which fills this form's original AcroForm
// fields directly), this POC uses the *flattened* copy (0 fields â€” see
// PDF-gen/reference-plain/A2408_18.pdf) and draws text at authored (page, x,
// y) positions instead, per PDF-gen's actual mission (any document, fielded
// or not). pdfgen-vanilla never built a coordinate map for this form (it only
// ever used 2408-18 via AcroForm), so DEFAULT_LAYOUT_2408_18 below was
// derived fresh from the real AcroForm widget rectangles in
// reference-acroform/A2408_18.pdf (inspected with pdf-lib), not guessed â€”
// each row's baseline y is that widget's y + 6 (nudges the baseline up off
// the very bottom of the widget's box). Front/back page row spacing is a
// uniform-fit approximation of the (very slightly uneven) real widget
// spacing â€” max drift under 1pt, and the Form Type Editor lets it be
// hand-tuned further if needed.
// ---------------------------------------------------------------------------

function emptyRow2408_18() {
  return { id: uid(), inspNo: "", item: "", ref: "", freq: "", nextDue: "", compAt: "" };
}

function emptyForm2408_18() {
  return {
    id: uid(),
    header: { nomenclature: "", model: "", serialNumber: "" },
    rows: [emptyRow2408_18()],
  };
}

function cloneForm2408_18(form) {
  return {
    id: uid(),
    header: { ...form.header },
    rows: form.rows.map(r => ({ ...r, id: uid() })),
  };
}

// Default field map: header field positions, shared row-column x/width, and
// the two pages' row grids (startY + per-row spacing, rows fixed by the
// physical form layout). All positions in PDF points, origin bottom-left.
// allowOverflow: true means "draw one unclipped line, may run past the
// column/box width" (matches how pdfgen-vanilla originally drew every field
// on this form type); false means "wrap within the box width instead."
const DEFAULT_LAYOUT_2408_18 = {
  header: {
    page:         { page: 0, x: 423.5, y: 769, width: 28,  fontSize: 8, allowOverflow: true },
    pageOf:       { page: 0, x: 474.5, y: 769, width: 28,  fontSize: 8, allowOverflow: true },
    nomenclature: { page: 0, x: 33,    y: 738, width: 193, fontSize: 8, allowOverflow: true },
    model:        { page: 0, x: 234,   y: 738, width: 130, fontSize: 8, allowOverflow: true },
    serialNumber: { page: 0, x: 371,   y: 738, width: 208, fontSize: 8, allowOverflow: true },
  },
  cols: {
    inspNo:  { x: 32,  width: 36,  fontSize: 7, allowOverflow: true },
    item:    { x: 76,  width: 150, fontSize: 7, allowOverflow: true },
    ref:     { x: 234, width: 130, fontSize: 7, allowOverflow: true },
    freq:    { x: 371, width: 65,  fontSize: 7, allowOverflow: true },
    nextDue: { x: 443, width: 36,  fontSize: 7, allowOverflow: true },
    compAt:  { x: 486, width: 93,  fontSize: 7, allowOverflow: true },
  },
  page1: { rows: 14, startY: 669.8, spacing: 23.94 },
  page2: { rows: 15, startY: 706.4, spacing: 24.04 },
  repeatingHeaderExclude: [],
};

function copies2408_18(form, layout) {
  return buildCoordinateCopies(TEMPLATE_2408_18_B64, form, layout || DEFAULT_LAYOUT_2408_18);
}

// Single-instance "Print Preview" path: fill this instance's copies, then
// merge them (if more than one) into one combined PDF. "Print All" instead
// calls copies2408_18 directly and merges across every instance/type in one
// pass â€” see buildCombinedPdf in index.html.
async function buildFilledPdf2408_18(form, layout) {
  const outDoc = await mergeCoordinateDocs(await copies2408_18(form, layout));
  return outDoc.save();
}

